'use strict';
(()=>{
 const canvas=document.getElementById('board'),c=canvas.getContext('2d'),pop=document.createElement('div');pop.className='fx-popup';pop.setAttribute('aria-live','polite');canvas.parentNode.append(pop);
 let particles=[],bands=[],life=0,age=0,shake=0,audio,volume=.45,reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches||false;
 const slider=document.getElementById('volume'),toggle=document.getElementById('reducedFX');toggle.checked=reduced;slider.oninput=()=>volume=Number(slider.value)/100;toggle.onchange=()=>{reduced=toggle.checked;particles=[];bands=[];canvas.style.transform=''};
 function note(freq,duration=.08,delay=0,wave='square',amp=.045,end=freq){if(volume===0)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});const t=audio.currentTime+delay,o=audio.createOscillator(),g=audio.createGain();o.type=wave;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),t+duration);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(amp*volume,t+.006);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(audio.destination);o.onended=()=>{o.disconnect();g.disconnect()};o.start(t);o.stop(t+duration+.01)}catch{}}
 function sfx(kind,enabled,count=1){if(!enabled)return;const melody=(notes,gap=.07)=>notes.forEach((n,i)=>note(n,.13,i*gap,'triangle',.09));switch(kind){case'tick':note(800,.06,0,'sine',.06);break;case'timeup':melody([784,659,523,1047],.13);break;case'move':note(170,.025,0,'square',.025);break;case'rotate':note(290,.055,0,'triangle',.07,570);break;case'lock':note(130,.09,0,'triangle',.11,48);break;case'drop':note(550,.12,0,'sawtooth',.045,65);note(80,.16,.08,'sine',.12,35);break;case'start':melody([262,330,392,523]);break;case'level':melody([392,494,587,784,988],.09);break;case'over':melody([330,262,196,98],.14);break;case'combo':melody([659,880],.07);break;case'clear':melody(count===4?[392,494,587,784,988,1175]:[330,440,554,659].slice(0,count+1));note(100,.14,0,'sine',.08,220);break;default:note(520,.08)}}
 function burst(rows,source,count,combo,points,levelUp){age=0;life=1100;bands=rows.slice();particles=[];shake=reduced?0:count===4?3:1;const palette=['#ffd87b','#e9ffa6','#8ee2de','#ef9ed4'];if(!reduced)for(const y of rows)for(let x=0;x<10;x++)for(let i=0;i<4;i++)particles.push({x:x*28+14,y:y*28+14,vx:(Math.random()-.5)*140,vy:-40-Math.random()*170,color:source[y][x]?['#75dada','#f1d764','#bd8ee6','#baff65','#ed8290','#7f9fec','#efa563'][source[y][x]-1]:palette[i],life:500+Math.random()*450});
 pop.textContent=[['','SINGLE!','DOUBLE!','TRIPLE!','FOUR LINES!'][count],`+${points}`,combo>1?`連續消行 ×${combo}`:'',levelUp?'LEVEL UP!':''].filter(Boolean).join('\n');
 }
 function step(ms,active=true){if(!active)return;age+=ms;life=Math.max(0,life-ms);particles.forEach(p=>{p.x+=p.vx*ms/1000;p.y+=p.vy*ms/1000;p.vy+=260*ms/1000;p.life-=ms});particles=particles.filter(p=>p.life>0);if(!life)pop.textContent='';if(shake&&age<170&&!reduced)canvas.style.transform=`translateX(${Math.sin(age/16)*shake}px)`;else canvas.style.transform=''}
 function draw(){if(!reduced&&age<260){c.globalAlpha=Math.max(0,1-age/260)*.7;c.fillStyle='#fff3b2';for(const y of bands)c.fillRect(0,y*28,280,28);c.globalAlpha=1}if(!reduced)for(const p of particles){c.globalAlpha=Math.min(1,p.life/300);c.fillStyle=p.color;c.fillRect(p.x,p.y,4,4)}c.globalAlpha=1}
 function reset(){particles=[];bands=[];life=0;shake=0;age=10000;pop.textContent='';canvas.style.transform=''}
 reset();window.arcadeFX={sound:sfx,burst,step,draw,reset};
})();
